#include <cstdio>
#include <cstdint>

// 强制按缓存行（64 字节）对齐：数组里每个元素都独占一行
struct alignas(64) CacheLine { long long v; };
// 强制 16 字节对齐：SIMD 友好
struct alignas(16) Vec4 { float x, y, z, w; };
// 不加约束：按最大成员自然对齐
struct Natural { char c; };

int main() {
    printf("CacheLine sizeof=%zu alignof=%zu\n", sizeof(CacheLine), alignof(CacheLine));
    printf("Vec4      sizeof=%zu alignof=%zu\n", sizeof(Vec4), alignof(Vec4));
    printf("Natural   sizeof=%zu alignof=%zu\n", sizeof(Natural), alignof(Natural));

    CacheLine obj;
    printf("对象地址 64 对齐: %d\n", (int)(((uintptr_t)&obj) % 64 == 0));
    printf("对齐被抬高: %d\n", (int)(alignof(CacheLine) > alignof(Natural)));
    return 0;
}
